    let selectedEditAvatarBg = '#6366f1';
    function selectEditAvatarBg(color, el) {
      selectedEditAvatarBg = color;
      document.querySelectorAll('#editProfileColorOptions .edit-avatar-swatch').forEach(s => s.style.border = 'none');
      if (el) el.style.border = '2px solid #fff';
    }

    let selectedEditCoverDataUrl = null;
    function handleEditProfileCoverSelect(event) {
      const file = event.target.files && event.target.files[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = function(e) {
        const img = new Image();
        img.onload = function() {
          const canvas = document.createElement('canvas');
          const maxW = 1200;
          const maxH = 400;
          let w = img.width;
          let h = img.height;
          if (w > maxW) { h = Math.round(h * (maxW / w)); w = maxW; }
          if (h > maxH) { w = Math.round(w * (maxH / h)); h = maxH; }
          canvas.width = w;
          canvas.height = h;
          const ctx = canvas.getContext('2d');
          ctx.drawImage(img, 0, 0, w, h);
          selectedEditCoverDataUrl = canvas.toDataURL('image/jpeg', 0.85);
          const preview = document.getElementById('editProfileCoverPreview');
          if (preview) {
            preview.style.background = 'url(' + selectedEditCoverDataUrl + ') center/cover no-repeat';
          }
          const removeBtn = document.getElementById('editProfileCoverRemoveBtn');
          if (removeBtn) removeBtn.style.display = 'inline-flex';
        };
        img.src = e.target.result;
      };
      reader.readAsDataURL(file);
    }

    function removeEditProfileCover() {
      selectedEditCoverDataUrl = '';
      const preview = document.getElementById('editProfileCoverPreview');
      if (preview) {
        preview.style.background = 'linear-gradient(135deg, #1e1b4b, #312e81)';
      }
      const removeBtn = document.getElementById('editProfileCoverRemoveBtn');
      if (removeBtn) removeBtn.style.display = 'none';
      const fileInput = document.getElementById('editProfileCoverInput');
      if (fileInput) fileInput.value = '';
    }

    function openEditProfileModal() {
      const m = document.getElementById('editProfileModal');
      if (!m) return;
      m.style.display = 'flex';
      const nameInput = document.getElementById('editProfileNameInput');
      const handleInput = document.getElementById('editProfileHandleInput');
      const bioInput = document.getElementById('editProfileBioInput');
      const websiteInput = document.getElementById('editProfileWebsiteInput');
      const preview = document.getElementById('editProfileAvatarPreview');
      const coverPreview = document.getElementById('editProfileCoverPreview');
      const photoRemoveBtn = document.getElementById('editProfilePhotoRemoveBtn');
      const coverRemoveBtn = document.getElementById('editProfileCoverRemoveBtn');

      if (myProfile) {
        if (nameInput) nameInput.value = myProfile.name || '';
        if (handleInput) handleInput.value = myProfile.handle || '';
        if (bioInput) bioInput.value = myProfile.bio || '';
        if (websiteInput) websiteInput.value = myProfile.website || '';
        selectedEditAvatarBg = myProfile.avatarBg || '#6366f1';
        selectedEditAvatarDataUrl = myProfile.avatarDataUrl || null;
        selectedEditCoverDataUrl = myProfile.coverDataUrl || null;

        if (photoRemoveBtn) photoRemoveBtn.style.display = myProfile.avatarDataUrl ? 'inline-flex' : 'none';
        if (coverRemoveBtn) coverRemoveBtn.style.display = myProfile.coverDataUrl ? 'inline-flex' : 'none';

        if (coverPreview) {
          if (myProfile.coverDataUrl) {
            coverPreview.style.background = 'url(' + myProfile.coverDataUrl + ') center/cover no-repeat';
          } else {
            coverPreview.style.background = 'linear-gradient(135deg, #1e1b4b, #312e81)';
          }
        }

        if (preview) {
          if (myProfile.avatarDataUrl) {
            preview.innerHTML = '<img src="' + myProfile.avatarDataUrl + '" style="width: 100%; height: 100%; object-fit: cover; border-radius: 50%; display: block;" />';
          } else {
            preview.innerHTML = '<span id="editProfileAvatarLetter">' + (myProfile.avatar || 'S') + '</span>';
            preview.style.background = myProfile.avatarBg || '#6366f1';
          }
        }
      }
    }

    function closeEditProfileModal() {
      const m = document.getElementById('editProfileModal');
      if (m) m.style.display = 'none';
    }

    async function saveEditedProfile() {
      const nameInput = document.getElementById('editProfileNameInput');
      const handleInput = document.getElementById('editProfileHandleInput');
      const bioInput = document.getElementById('editProfileBioInput');
      const websiteInput = document.getElementById('editProfileWebsiteInput');

      const newName = (nameInput && nameInput.value.trim()) ? nameInput.value.trim() : (myProfile ? myProfile.name : 'Sovereign Node');
      let rawHandle = (handleInput && handleInput.value.trim()) ? handleInput.value.trim() : (myProfile ? myProfile.handle : '@user');
      if (!rawHandle.startsWith('@')) rawHandle = '@' + rawHandle;
      const newBio = bioInput ? bioInput.value.trim() : '';
      const newWebsite = (websiteInput && websiteInput.value.trim()) ? websiteInput.value.trim() : '';

      const updatedPayload = {
        did: myProfile ? myProfile.did : ('did:sovra:user_' + Math.random().toString(36).substring(2, 8)),
        handle: rawHandle,
        name: newName,
        displayName: newName,
        avatar: newName.charAt(0).toUpperCase(),
        avatarDataUrl: selectedEditAvatarDataUrl !== null ? selectedEditAvatarDataUrl : (myProfile ? (myProfile.avatarDataUrl || '') : ''),
        avatarBg: selectedEditAvatarBg,
        bio: newBio,
        website: newWebsite,
        coverDataUrl: selectedEditCoverDataUrl !== null ? selectedEditCoverDataUrl : (myProfile ? (myProfile.coverDataUrl || '') : ''),
        device: isMobileDevice ? 'Mobile' : 'Desktop'
      };

      try {
        const res = await fetch('/api/user/update', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(updatedPayload)
        });
        const data = await res.json();
        if (!res.ok || !data.ok) {
          alert('Could not update profile: ' + (data.error || 'Server error'));
          return;
        }

        myProfile = data.user;
        currentUserHandle = myProfile.handle;
        try {
          localStorage.setItem('sovra_user_profile', JSON.stringify(myProfile));
          if (myProfile.sessionToken) localStorage.setItem('sovra_session_token', myProfile.sessionToken);
        } catch (e) {}

        fetch('/api/peers/register', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(myProfile)
        }).catch(function() {});

        updateUserDisplayInUI();
        closeEditProfileModal();
        showAccountToast('Profile saved to database and announced to peer mesh!');
      } catch (err) {
        alert('Network error while updating profile: ' + err);
      }
    }

    let womHandleCheckTimer = null;
    function validateWomHandleLive(rawHandle) {
      if (womHandleCheckTimer) clearTimeout(womHandleCheckTimer);
      const feedback = document.getElementById('womHandleFeedback');
      const errorBox = document.getElementById('womErrorMsg');
      if (errorBox) errorBox.style.display = 'none';
      if (!feedback) return;

      const trimmed = (rawHandle || '').trim().replace(/^@/, '');
      if (!trimmed) {
        feedback.innerText = 'Checked on P2P Mesh';
        feedback.style.color = '#94a3b8';
        return;
      }

      feedback.innerText = 'Checking...';
      feedback.style.color = '#38bdf8';

      womHandleCheckTimer = setTimeout(() => {
        fetch('/api/user/check-handle?handle=' + encodeURIComponent('@' + trimmed))
          .then(r => r.json())
          .then(data => {
            if (data.ok) {
              if (data.isAvailable) {
                feedback.innerText = '✓ Available';
                feedback.style.color = '#10b981';
              } else {
                feedback.innerText = '✕ Already Taken';
                feedback.style.color = '#f87171';
              }
            }
          })
          .catch(() => {
            feedback.innerText = 'Checked on P2P Mesh';
            feedback.style.color = '#94a3b8';
          });
      }, 250);
    }

    // Auto-check onboarding on first visit & restore session from server
    window.addEventListener('DOMContentLoaded', function() {
      const isExplicitlyLoggedOut = localStorage.getItem('sovra_logged_out') === 'true';
      const sessionToken = localStorage.getItem('sovra_session_token');
      const savedProfile = localStorage.getItem('sovra_user_profile');

      if (isExplicitlyLoggedOut || !sessionToken || !savedProfile) {
        updateUserDisplayInUI();
        showAuthLandingGate();
        return;
      }

      if (sessionToken) {
        fetch('/api/user/me?sessionToken=' + encodeURIComponent(sessionToken))
          .then(r => r.json())
          .then(data => {
            if (data.ok && data.user) {
              myProfile = data.user;
              currentUserHandle = myProfile.handle;
              try { localStorage.setItem('sovra_user_profile', JSON.stringify(myProfile)); } catch(e) {}
              updateUserDisplayInUI();
              // Register heartbeat with server
              fetch('/api/peers/register', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(myProfile)
              }).catch(function() {});
            } else {
              myProfile = null;
              currentUserHandle = '@guest';
              localStorage.removeItem('sovra_user_profile');
              localStorage.removeItem('sovra_session_token');
              updateUserDisplayInUI();
              showAuthLandingGate();
            }
          })
          .catch(() => {
            if (myProfile) updateUserDisplayInUI();
            else showAuthLandingGate();
          });
      } else {
        updateUserDisplayInUI();
        showAuthLandingGate();
      }

      if (isMobileDevice && !isSovraAppInstalled()) {
        setTimeout(function() {
          if (isSovraAppInstalled()) return;
          const topBtn = document.getElementById('pwaInstallBtn');
          if (topBtn) topBtn.style.display = 'inline-flex';
          const banner = document.getElementById('pwaInstallBanner');
          if (banner && !sessionStorage.getItem('pwa_dismissed')) {
            banner.style.display = 'flex';
          }
        }, 1200);
      } else {
        const topBtn = document.getElementById('pwaInstallBtn');
        if (topBtn) topBtn.style.display = 'none';
        const banner = document.getElementById('pwaInstallBanner');
        if (banner) banner.style.display = 'none';
      }
      setTimeout(function() {
        if (typeof syncFriendsRelationships === 'function') syncFriendsRelationships();
        if (typeof renderRightRailSuggestions === 'function') renderRightRailSuggestions();
        if (typeof renderTrendingHashtags === 'function') renderTrendingHashtags();
        if (typeof updateProfileDynamicStats === 'function') updateProfileDynamicStats();
      }, 400);
      setInterval(function() {
        if (typeof updateProfileDynamicStats === 'function') updateProfileDynamicStats();
      }, 5000);
      setInterval(function() {
        if (typeof renderTrendingHashtags === 'function') renderTrendingHashtags();
      }, 30000);
    });

    // ==========================================
    // 🛡️ SOVEREIGN 2FA / TOTP & SECURITY PIN LOGIC
    // ==========================================
    var currentTotpSecret = '';

    function openSovereignMfaModal(event) {
      if (event && event.stopPropagation) event.stopPropagation();
      var m = document.getElementById('sovereignMfaModal');
      if (m) {
        m.style.zIndex = '100000';
        m.style.display = 'flex';
      }
      switchMfaTab('totp');
      clearMfaNotice();
      loadTotpSetupData();
      renderMfaRecoveryPhrase();
    }

    function closeSovereignMfaModal() {
      var m = document.getElementById('sovereignMfaModal');
      if (m) m.style.display = 'none';
      clearMfaNotice();
    }

    function showMfaNotice(msg, isSuccess) {
      var box = document.getElementById('mfaModalNotice');
      if (!box) return;
      box.innerText = msg;
      box.style.display = 'block';
      if (isSuccess) {
        box.style.background = 'rgba(16, 185, 129, 0.15)';
        box.style.border = '1px solid rgba(16, 185, 129, 0.4)';
        box.style.color = '#34d399';
      } else {
        box.style.background = 'rgba(239, 68, 68, 0.15)';
        box.style.border = '1px solid rgba(239, 68, 68, 0.4)';
        box.style.color = '#f87171';
      }
    }

    function clearMfaNotice() {
      var box = document.getElementById('mfaModalNotice');
      if (box) {
        box.style.display = 'none';
        box.innerText = '';
      }
    }

    function switchMfaTab(tab) {
      var tabs = ['totp', 'pin', 'recovery'];
      tabs.forEach(function(t) {
        var btn = document.getElementById('mfaTab' + t.charAt(0).toUpperCase() + t.slice(1) + 'Btn');
        var section = document.getElementById('mfaSection' + t.charAt(0).toUpperCase() + t.slice(1));
        if (btn) {
          if (t === tab) {
            btn.style.background = '#3b82f6';
            btn.style.color = '#fff';
          } else {
            btn.style.background = 'transparent';
            btn.style.color = '#94a3b8';
          }
        }
        if (section) {
          section.style.display = (t === tab) ? 'block' : 'none';
        }
      });
      clearMfaNotice();
    }

    function updateMfaStatusView(isEnabled) {
      var badge = document.getElementById('mfaTotpBadge');
      var setupView = document.getElementById('mfaTotpSetupView');
      var activeView = document.getElementById('mfaTotpActiveView');
      if (badge) {
        if (isEnabled) {
          badge.innerText = '● Active';
          badge.style.background = 'rgba(16, 185, 129, 0.2)';
          badge.style.color = '#10b981';
        } else {
          badge.innerText = 'Disabled';
          badge.style.background = 'rgba(239, 68, 68, 0.2)';
          badge.style.color = '#f87171';
        }
      }
      if (setupView) setupView.style.display = isEnabled ? 'none' : 'block';
      if (activeView) activeView.style.display = isEnabled ? 'block' : 'none';

      if (myProfile) myProfile.totpEnabled = isEnabled;
    }

    async function loadTotpSetupData() {
      var token = localStorage.getItem('sovra_session_token') || (myProfile && myProfile.sessionToken) || (window.SOVRA_HOST_SESSION ? window.SOVRA_HOST_SESSION.token : '') || '';
      try {
        var res = await fetch('/api/auth/totp/setup', {
          headers: {
            'Authorization': 'Bearer ' + token,
            'x-sovra-session-token': token
          }
        });
        var data = await res.json();
        if (data && data.ok) {
          currentTotpSecret = data.secret || '';
          var secretEl = document.getElementById('mfaTotpSecretKey');
          if (secretEl) secretEl.innerText = data.secret;
          var qrContainer = document.getElementById('mfaTotpQrContainer');
          if (qrContainer && data.otpauthUri) {
            qrContainer.innerHTML = generateSvgQrCode(data.otpauthUri);
          }
          updateMfaStatusView(Boolean(data.totpEnabled));
        }
      } catch (e) {
        console.warn('Failed to fetch TOTP setup:', e);
      }
    }

    function copyTotpSecretKey() {
      if (!currentTotpSecret) return;
      copyToClipboard(currentTotpSecret, function(success) {
        if (success) {
          showMfaNotice('📋 Authenticator Secret Key copied to clipboard!', true);
          showAccountToast('📋 Secret key copied for Google Authenticator');
        } else {
          prompt('Copy Authenticator Secret Key:', currentTotpSecret);
        }
      });
    }

    async function submitVerifyTotpSetup() {
      var input = document.getElementById('mfaTotpVerifyInput');
      var code = input ? input.value.trim() : '';
      if (!code || code.length !== 6) {
        showMfaNotice('Please enter a valid 6-digit code from your authenticator app.', false);
        return;
      }
      var btn = document.getElementById('mfaTotpVerifyBtn');
      if (btn) {
        btn.disabled = true;
        btn.innerText = 'Verifying Authenticator Code...';
      }
      var token = localStorage.getItem('sovra_session_token') || (myProfile && myProfile.sessionToken) || (window.SOVRA_HOST_SESSION ? window.SOVRA_HOST_SESSION.token : '') || '';
      try {
        var res = await fetch('/api/auth/totp/verify', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': 'Bearer ' + token,
            'x-sovra-session-token': token
          },
          body: JSON.stringify({ code: code })
        });
        var data = await res.json();
        if (!res.ok || !data.ok) {
          showMfaNotice(data.error || 'Invalid 6-digit code. Please check your authenticator clock and retry.', false);
          return;
        }
        if (input) input.value = '';
        showMfaNotice('✅ Google Authenticator 2FA activated successfully!', true);
        showAccountToast('🛡️ 2FA Activated! Account is now protected by Authenticator.');
        updateMfaStatusView(true);
      } catch (err) {
        showMfaNotice('Network failure: ' + (err.message || err), false);
      } finally {
        if (btn) {
          btn.disabled = false;
          btn.innerHTML = '<span>Verify &amp; Activate 2FA</span> <span>✓</span>';
        }
      }
    }

    async function submitDisableTotp() {
      var pinInput = document.getElementById('mfaDisablePinInput');
      var pin = pinInput ? pinInput.value.trim() : '';
      if (!pin) {
        showMfaNotice('Please enter your 6-digit Security PIN to disable 2FA.', false);
        return;
      }
      var btn = document.getElementById('mfaDisableTotpBtn');
      if (btn) {
        btn.disabled = true;
        btn.innerText = 'Disabling...';
      }
      var token = localStorage.getItem('sovra_session_token') || (myProfile && myProfile.sessionToken) || (window.SOVRA_HOST_SESSION ? window.SOVRA_HOST_SESSION.token : '') || '';
      try {
        var res = await fetch('/api/auth/totp/disable', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': 'Bearer ' + token,
            'x-sovra-session-token': token
          },
          body: JSON.stringify({ pin: pin })
        });
        var data = await res.json();
        if (!res.ok || !data.ok) {
          showMfaNotice(data.error || 'Failed to disable 2FA. Incorrect PIN.', false);
          return;
        }
        if (pinInput) pinInput.value = '';
        showMfaNotice('2FA has been disabled. You can re-enable anytime.', true);
        showAccountToast('⚠️ 2FA Disabled.');
        updateMfaStatusView(false);
      } catch (err) {
        showMfaNotice('Network failure: ' + (err.message || err), false);
      } finally {
        if (btn) {
          btn.disabled = false;
          btn.innerText = 'Disable Authenticator 2FA';
        }
      }
    }

    async function submitUpdatePin() {
      var oldPinInput = document.getElementById('mfaOldPinInput');
      var newPinInput = document.getElementById('mfaNewPinInput');
      var oldPin = oldPinInput ? oldPinInput.value.trim() : '';
      var newPin = newPinInput ? newPinInput.value.trim() : '';
      if (!oldPin) {
        showMfaNotice('Please enter your current Security PIN (default: 123456).', false);
        return;
      }
      if (!newPin || newPin.length < 4 || newPin.length > 8) {
        showMfaNotice('New PIN must be between 4 and 8 digits.', false);
        return;
      }
      var btn = document.getElementById('mfaUpdatePinBtn');
      if (btn) {
        btn.disabled = true;
        btn.innerText = 'Updating PIN...';
      }
      var token = localStorage.getItem('sovra_session_token') || (myProfile && myProfile.sessionToken) || (window.SOVRA_HOST_SESSION ? window.SOVRA_HOST_SESSION.token : '') || '';
      try {
        var res = await fetch('/api/auth/pin/update', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': 'Bearer ' + token,
            'x-sovra-session-token': token
          },
          body: JSON.stringify({ oldPin: oldPin, newPin: newPin })
        });
        var data = await res.json();
        if (!res.ok || !data.ok) {
          showMfaNotice(data.error || 'Failed to update PIN. Incorrect current PIN.', false);
          return;
        }
        if (oldPinInput) oldPinInput.value = '';
        if (newPinInput) newPinInput.value = '';
        try { localStorage.setItem('sovra_lock_pin', newPin); } catch(e) {}
        var pinBadge = document.getElementById('almCurrentPinBadge');
        if (pinBadge) pinBadge.innerText = newPin;
        showMfaNotice('✅ Security PIN updated successfully!', true);
        showAccountToast('🔒 Security PIN updated successfully!');
      } catch (err) {
        showMfaNotice('Network failure: ' + (err.message || err), false);
      } finally {
        if (btn) {
          btn.disabled = false;
          btn.innerHTML = '<span>Update Security PIN</span> <span>✓</span>';
        }
      }
    }

    function generateClientDeterministicPhrase(seedStr) {
      var wordPool = [
        'galaxy', 'matrix', 'beacon', 'titan', 'solar', 'quantum', 'pulse', 'harbor', 'orbit', 'zenith',
        'vector', 'cipher', 'nexus', 'prism', 'cosmos', 'shield', 'echo', 'flux', 'vortex', 'radiant',
        'anchor', 'crystal', 'vertex', 'aurora', 'signal', 'bastion', 'strata', 'shadow', 'canyon', 'falcon',
        'alpha', 'bravo', 'cosmic', 'drift', 'ember', 'frost', 'gravity', 'horizon', 'ion', 'jupiter',
        'kinetic', 'lunar', 'meteor', 'nebula', 'omega', 'plasma', 'quasar', 'stellar', 'transit', 'umbra'
      ];
      var seed = String(seedStr || ('sovra_' + Date.now()));
      var h = 0x811c9dc5;
      for (var i = 0; i < seed.length; i++) {
        h ^= seed.charCodeAt(i);
        h = Math.imul(h, 0x01000193);
      }
      var selected = [];
      for (var j = 0; j < 12; j++) {
        var idx = Math.abs((h ^ (j * 0x45d9f3b)) % wordPool.length);
        selected.push(wordPool[idx]);
        h = Math.imul(h ^ idx, 0x01000193);
      }
      return selected.join(' ');
    }

    function renderMfaRecoveryPhrase() {
      var grid = document.getElementById('mfaRecoveryWordsGrid');
      if (!grid) return;

      function renderPhrase(phrase) {
        if (!phrase) return;
        var words = phrase.trim().split(' ').map(function(w) { return w.trim(); }).filter(Boolean);
        var html = '';
        for (var i = 0; i < words.length; i++) {
          html += '<div style="background: rgba(255,255,255,0.05); padding: 8px 10px; border-radius: 8px; border: 1px solid rgba(255,255,255,0.08); display: flex; align-items: center; gap: 6px; min-width: 0; overflow: hidden;">' +
            '<span style="font-size: 0.7rem; color: #64748b; font-weight: 700; width: 18px; flex-shrink: 0;">' + (i + 1) + '.</span>' +
            '<span style="font-size: 0.82rem; font-family: monospace; color: #38bdf8; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">' + words[i] + '</span>' +
            '</div>';
        }
        grid.innerHTML = html;
      }

      if (myProfile && myProfile.recoveryPhrase && myProfile.recoveryPhrase.trim()) {
        renderPhrase(myProfile.recoveryPhrase);
        return;
      }

      // Fetch uniquely generated seed phrase from backend for this authenticated account
      var token = (myProfile && myProfile.sessionToken) || localStorage.getItem('sovra_session_token') || '';
      var url = '/api/user/recovery-phrase' + (token ? ('?sessionToken=' + encodeURIComponent(token)) : '');
      var headers = token ? { 'Authorization': 'Bearer ' + token } : {};

      fetch(url, { headers: headers })
        .then(function(r) { return r.json(); })
        .then(function(data) {
          if (data && data.ok && data.recoveryPhrase) {
            if (myProfile) {
              myProfile.recoveryPhrase = data.recoveryPhrase;
              try { localStorage.setItem('sovra_user_profile', JSON.stringify(myProfile)); } catch(e) {}
            }
            renderPhrase(data.recoveryPhrase);
          } else {
            var fallback = generateClientDeterministicPhrase(myProfile ? (myProfile.did || myProfile.handle) : '');
            if (myProfile) myProfile.recoveryPhrase = fallback;
            renderPhrase(fallback);
          }
        })
        .catch(function() {
          var fallback = generateClientDeterministicPhrase(myProfile ? (myProfile.did || myProfile.handle) : '');
          if (myProfile) myProfile.recoveryPhrase = fallback;
          renderPhrase(fallback);
        });
    }

    function copyRecoveryPhrase() {
      var phrase = (myProfile && myProfile.recoveryPhrase) ? myProfile.recoveryPhrase : '';
      if (!phrase) {
        var grid = document.getElementById('mfaRecoveryWordsGrid');
        if (grid) {
          var wordSpans = grid.querySelectorAll('span:nth-child(2)');
          if (wordSpans && wordSpans.length >= 12) {
            var extracted = [];
            for (var i = 0; i < wordSpans.length; i++) extracted.push(wordSpans[i].textContent.trim());
            phrase = extracted.join(' ');
          }
        }
      }
      if (!phrase) {
        phrase = generateClientDeterministicPhrase(myProfile ? (myProfile.did || myProfile.handle) : '');
        if (myProfile) myProfile.recoveryPhrase = phrase;
      }
      copyToClipboard(phrase, function(success) {
        if (success) {
          showMfaNotice('📋 12-Word Recovery Phrase copied to clipboard!', true);
          showAccountToast('📋 12-Word Recovery Phrase copied!');
        } else {
          prompt('Copy Recovery Phrase:', phrase);
        }
      });
    }

